import{c as a,Q as s,j as e,m as d}from"./chunks/framework.DOi4mjdC.js";const n="/assets/%E7%BB%98%E5%9B%BE1.CMDhYPdU.png",u=JSON.parse('{"title":"随路转换DN2NZ搬运（ISASI）","description":"","frontmatter":{},"headers":[{"level":1,"title":"随路转换DN2NZ搬运（ISASI）","slug":"随路转换dn2nz搬运isasi"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"通路说明","slug":"通路说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Memory数据搬运/DataCopy/随路转换DN2NZ搬运（ISASI）.md","filePath":"api/SIMD-API/基础API/Memory数据搬运/DataCopy/随路转换DN2NZ搬运（ISASI）.md"}'),l={name:"api/SIMD-API/基础API/Memory数据搬运/DataCopy/随路转换DN2NZ搬运（ISASI）.md"};function r(i,t,p,o,c,h){return s(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="随路转换dn2nz搬运-isasi" tabindex="-1">随路转换DN2NZ搬运（ISASI） <a class="header-anchor" href="#随路转换dn2nz搬运-isasi" aria-label="Permalink to &quot;随路转换DN2NZ搬运（ISASI）&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>随路格式转换数据搬运，适用于在搬运时进行格式转换。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool enableSmallC0 = false&gt;</span></span>\n<span class="line"><span>__aicore__ inline void DataCopy(const LocalTensor&lt;T&gt;&amp; dst, const GlobalTensor&lt;T&gt;&amp; src, const Dn2NzParams&amp; intriParams);</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>源操作数或者目的操作数的数据类型。</td></tr><tr><td>enableSmallC0</td><td>SmallC0模式开关：当dValue小于等于4的时候，C0_SIZE会补齐到4 * sizeof(T) Bytes，默认不开启。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为GlobalTensor。</td></tr><tr><td>intriParams</td><td>输入</td><td>搬运参数，Dn2NzParams类型，具体参数说明请参考表Dn2NzParams结构体参数定义；具体定义请参考${INSTALL_DIR}/include/ascendc/basic_api/interface/kernel_struct_data_copy.h，${INSTALL_DIR}请替换为CANN软件安装后文件存储路径。</td></tr></tbody></table><p><strong>表 3</strong> Dn2NzParams结构体参数定义</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>dnNum</td><td>传输DN矩阵的数目，取值范围：ndNum∈[0, 4095]。</td></tr><tr><td>nValue</td><td>DN矩阵的行数，取值范围：nValue∈[0, 16384]。</td></tr><tr><td>dValue</td><td>DN矩阵的列数，取值范围：dValue∈[0, 2^32-1]。</td></tr><tr><td>srcDnMatrixStride</td><td>源操作数相邻DN矩阵起始地址间的偏移，取值范围：srcDNMatrixStride∈[0, 2^64-1]，单位为元素。</td></tr><tr><td>srcDValue</td><td>源操作数同一DN矩阵的相邻行起始地址间的偏移，取值范围：srcDValue∈[1, 2^64-1]，单位为元素。</td></tr><tr><td>dstNzC0Stride</td><td>DN转换到NZ格式后，源操作数中的一列会转换为目的操作数的多行。dstNzC0Stride表示，目的NZ矩阵中，来自源操作数同一列的多行数据相邻行起始地址间的偏移，取值范围：dstNzC0Stride∈[1, 65535]，单位：C0_SIZE（32B）。</td></tr><tr><td>dstNzNStride</td><td>目的NZ矩阵中，Z型矩阵相邻行起始地址之间的偏移。取值范围：dstNzNStride∈[1, 65535]，单位：C0_SIZE（32B）。</td></tr><tr><td>dstNzMatrixStride</td><td>目的NZ矩阵中，相邻NZ矩阵起始地址间的偏移，取值范围：dstNzMatrixStride∈[1, 2^32-1]，单位为元素。</td></tr></tbody></table><p>DN2NZ转换示意图如下，样例中参数设置值和解释说明如下（以half数据类型为例）：</p><ul><li>dnNum = 2，表示传输DN矩阵的数目为2。</li><li>nValue = 8，DN矩阵的列数，也就是矩阵的宽度为8。</li><li>dValue = 24，DN矩阵的行数，也就是矩阵的高度为24个元素。</li><li>srcDnMatrixStride = 96，表达相邻DN矩阵起始地址间的偏移，即：A1与C1之间的间隔，为6个DataBlock，6 * 16 = 96个元素。</li><li>srcDValue = 48, 表示一行的所含元素个数，即为3个DataBlock, 3 * 16 = 48个元素。</li><li>dstNzC0Stride = 6。DN转换到NZ格式后，源操作数中的一列会转换为目的操作数的多列，例如src中A1和A2为1列，dst中A1和A2被分为2列。多列数据起始地址之间的偏移就是A1和A2在dst中的偏移，偏移为6个datablock。</li><li>dstNzNStride = 2，表达dst中第x个目的DN矩阵和第x+1个目的DN矩阵的起点的偏移，即A1与B1之间的间隔，即为2个DataBlock。</li><li>dstNzMatrixStride = 64，表达dst中第x个目的ND矩阵和第x+1个目的ND矩阵的起点的偏移，即A1和C1之间的距离，即为4个DataBlock，4 * 16 = 64个元素。</li></ul><p><img src="'+n+`" alt=""></p><h2 id="通路说明" tabindex="-1">通路说明 <a class="header-anchor" href="#通路说明" aria-label="Permalink to &quot;通路说明&quot;">​</a></h2><p><strong>表 4</strong> 数据通路和数据类型</p><table tabindex="0"><thead><tr><th>支持型号</th><th>数据通路（通过TPosition表达）</th><th>源操作数和目的操作数的数据类型 (两者保持一致)</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>GM -&gt; A1/B1</td><td>int8_t、uint8_t、fp4x2_e2m1_t、fp4x2_e1m2_t、int16_t、uint16_t、int32_t、uint32_t、half、bfloat16_t、float</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// dstLocal: 存放DataCopy的输出Tensor，仅支持A1/B1</span></span>
<span class="line"><span>// srcGlobal：存放DataCopy的输入Tensor，仅支持GM</span></span>
<span class="line"><span></span></span>
<span class="line"><span>AscendC::Dn2NzParams dn2nzParams(</span></span>
<span class="line"><span>    /* dnNum             */ 1,</span></span>
<span class="line"><span>    /* nValue            */ 32,</span></span>
<span class="line"><span>    /* dValue            */ 32,</span></span>
<span class="line"><span>    /* srcDnMatrixStride */ 0,</span></span>
<span class="line"><span>    /* srcDValue         */ 32,</span></span>
<span class="line"><span>    /* dstNzC0Stride     */ 32,</span></span>
<span class="line"><span>    /* dstNzNStride      */ 1,</span></span>
<span class="line"><span>    /* dstNzMatrixStride */ 0</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>// 将GM中DN的格式的数据， 按照 dn2nzParams 定义的规则，转换为NZ并拷贝到A1/B1中</span></span>
<span class="line"><span>AscendC::DataCopy(dstLocal, srcGlobal, dn2nzParams);</span></span></code></pre></div>`,26)])])}const b=a(l,[["render",r]]);export{u as __pageData,b as default};
